        raise ValueError('invalid permanent service registry')
    if not isinstance(observed,list) or len(set(observed))!=len(observed) or any(not isinstance(name,str) or re.fullmatch(pattern,name) is None for name in observed):
        raise ValueError('invalid observed service names')
    missing=sorted(set(registered)-set(observed))
    unknown=sorted(name for name in observed if name not in registered and not name.startswith('build-'))
    selected=set(registered)&set(observed)
    return {'include':'('+'|'.join(name.replace('.','[.]') for name in sorted(registered))+')',
            'exclude':r'.+\.(automount|device|mount|scope|slice)',
            'missing':missing,'unregistered':unknown,'scope_complete':not missing and not unknown,
            'selected_unit_state_series':5*len(selected),'rollback_extra_unit_state_series':5*(len(observed)-len(selected))}
