"""Owned typed systemd endpoint on a real nonroot private D-Bus; never host systemd."""
import asyncio,contextlib,json,os,pathlib,signal,socket,subprocess,sys,tempfile,time,urllib.request
from dbus_next import Message,MessageType,Variant
from dbus_next.aio import MessageBus
DEST='org.freedesktop.systemd1';ROOT_PATH='/org/freedesktop/systemd1'
DENIED='org.freedesktop.DBus.Error.AccessDenied'

def unit_path(name):
 return ROOT_PATH+'/unit/'+''.join(c if c.isascii() and c.isalnum() else '_'+format(ord(c),'02x') for c in name)

async def provider(address,catalog):
 bus=await MessageBus(bus_address=address).connect()
 unrelated=await MessageBus(bus_address=address).connect()
 await bus.request_name(DEST);await unrelated.request_name('org.opsforge.Unrelated')
 def handler(message):
  if message.message_type!=MessageType.METHOD_CALL:return
  if message.interface=='org.opsforge.Unrelated' and message.member=='Ping':
   return Message.new_method_return(message,signature='s',body=['old-permission'])
  if message.interface==DEST+'.Manager' and message.member=='ListUnits':
   rows=[[name,'controlled fixture','loaded',state,'running' if state=='active' else 'failed','',unit_path(name),0,'','/'] for name,state in catalog.items()]
   return Message.new_method_return(message,signature='a(ssssssouso)',body=[rows])
  if message.interface=='org.freedesktop.DBus.Properties' and message.member=='Get':
   interface,prop=message.body
   values={(ROOT_PATH,DEST+'.Manager','Version'):'252.0',
           (ROOT_PATH,DEST+'.Manager','SystemState'):'running'}
   values.update({(unit_path(name),DEST+'.Service','Type'):'simple' for name in catalog})
   value=values.get((message.path,interface,prop))
   if value is not None:return Message.new_method_return(message,signature='v',body=[Variant('s',value)])
  if message.interface==DEST+'.Manager' and message.member in ('StartUnit','RestartUnit'):
   return Message.new_method_return(message,signature='o',body=[ROOT_PATH+'/job/1'])
  return Message.new_error(message,'org.freedesktop.DBus.Error.UnknownMethod','controlled endpoint has no such method')
 bus.add_message_handler(handler);unrelated.add_message_handler(handler)
 print('PRIVATE_TYPED_PROVIDER_READY',flush=True)
 try:await asyncio.Future()
 finally:bus.disconnect();unrelated.disconnect()

class PrivateSystemd:
 def __init__(self,root,catalog):
  self.root=pathlib.Path(root);self.catalog=catalog;self.address='unix:path='+str(self.root/'bus.sock')
  self.config=self.root/'bus.conf';self.processes=[];self.logs=[]
 def start(self):
  self.initial='<busconfig><type>session</type><listen>'+self.address+'</listen><auth>EXTERNAL</auth><apparmor mode="disabled"/><policy context="default"><allow user="*"/><allow own="*"/><allow send_destination="*"/><allow receive_sender="*"/><deny send_destination="'+DEST+'"/></policy></busconfig>'
  self.config.write_text(self.initial)
  self.spawn('daemon',['dbus-daemon','--nofork','--nopidfile','--config-file='+str(self.config)])
  deadline=time.monotonic()+4
  while not (self.root/'bus.sock').exists():
   assert self.processes[0].poll() is None and time.monotonic()<deadline,self.logtext();time.sleep(.02)
  self.spawn('provider',[sys.executable,'-B',__file__,'--provider',self.address,json.dumps(self.catalog)])
  while 'PRIVATE_TYPED_PROVIDER_READY' not in self.logtext():
   assert all(p.poll() is None for p in self.processes) and time.monotonic()<deadline,self.logtext();time.sleep(.02)
  return self
 def spawn(self,name,args,env=None):
  log=(self.root/(name+'.log')).open('wb');self.logs.append(log)
  process=subprocess.Popen(args,stdout=log,stderr=log,env=env);self.processes.append(process);return process
 def logtext(self):
  return '\n'.join(p.read_text(errors='replace') for p in self.root.glob('*.log'))
 def reload(self,xml):
  self.config.write_text(xml);self.processes[0].send_signal(signal.SIGHUP)
 def call(self,member,destination=DEST,interface=None,signature='',body=None):
  async def once():
   client=await MessageBus(bus_address=self.address).connect()
   try:return await asyncio.wait_for(client.call(Message(destination=destination,path=ROOT_PATH,interface=interface or DEST+'.Manager',member=member,signature=signature,body=body or [])),2)
   finally:client.disconnect()
  return asyncio.run(once())
 def old_permission(self):
  result=self.call('Ping','org.opsforge.Unrelated','org.opsforge.Unrelated')
  assert result.message_type==MessageType.METHOD_RETURN and result.body==['old-permission'],(result.error_name,result.body)
 def admin_denied(self):
  for member in ('StartUnit','RestartUnit'):
   result=self.call(member,signature='ss',body=[next(iter(self.catalog)),'replace'])
   assert result.message_type==MessageType.ERROR and result.error_name==DENIED,'service administration became accessible'
 def close(self):
  for process in reversed(self.processes):
   if process.poll() is None:process.terminate()
   try:process.wait(timeout=3)
   except subprocess.TimeoutExpired:process.kill();process.wait(timeout=3)
