  base='http://127.0.0.1:'+str(port)
  def scrape():
   with urllib.request.urlopen(base+'/metrics',timeout=3) as response:
    assert response.status==200;return response.read().decode()
  deadline=time.monotonic()+5
  try:
   while True:
    try:
     with urllib.request.urlopen(base+'/',timeout=.3):break
    except OSError:
     assert process.poll() is None and time.monotonic()<deadline,self.logtext();time.sleep(.03)
   yield scrape
  finally:
   if process.poll() is None:process.terminate()
   try:process.wait(timeout=3)
   except subprocess.TimeoutExpired:process.kill();process.wait(timeout=3)

